class DatabaseNotice extends Illuminate\Notifications\Notification
{
    public function via($notifiable): array
    {
        return ['database'];
    }

    public function toDatabase($notifiable): array
    {
        return ['message' => 'Hello'];
    }
}
class CorrelatedNotice extends DatabaseNotice implements Illuminate\Contracts\Queue\ShouldQueue
{
    use Illuminate\Bus\Queueable;

    public function via($notifiable): array
    {
        return ['mail', 'database'];
    }
}
$other = Member::create(['name' => 'Lin', 'email' => 'lin@example.test']);
Illuminate\Support\Facades\Notification::send([$member, $other], new CorrelatedNotice());
